<?php
declare(strict_types=1);
$GLOBALS['DB_ROUTE_INSPECT']=true;$GLOBALS['NV_HEALTH_READ_ONLY']=true;
require __DIR__.'/includes/config.php';require __DIR__.'/includes/layout.php';require __DIR__.'/includes/backup_lib.php';require __DIR__.'/includes/system_health.php';
if(!is_super())deny('Pemeriksaan kesehatan hanya untuk Super Admin.');
$version=json_decode(file_get_contents(__DIR__.'/app-version.json'),true);
$health=new NaveenaSystemHealth(['app'=>APP_DIR,'storage'=>db_store_root(),'uploads'=>local_upload_dir(),'backup'=>NaveenaSystemHealth::backupRoot(),'system'=>nv_system_root(APP_DIR),'schema'=>SCHEMA_VERSION,'version'=>$version['version']]);
$error='';$report=null;
try{
    if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=(string)($_POST['action']??'');if($action==='run'){$report=$health->run((string)($_POST['mode']??'quick'));$health->audit('run', (int)current_user()['id'], ['id'=>$report['id'],'mode'=>$report['mode']]);}elseif($action==='retention'){$health->setRetention((int)($_POST['keep']??30));$health->audit('retention',(int)current_user()['id'],['keep'=>$health->retention()]);}else throw new RuntimeException('Tindakan tidak sah.');}
    if(isset($_GET['id']))$report=$health->read((string)$_GET['id']);
    if(isset($_GET['export'])){$r=$health->read((string)$_GET['export']);header('Content-Type: application/json; charset=utf-8');header('Content-Disposition: attachment; filename="naveena-health-'.$r['id'].'.json"');header('Cache-Control: no-store');echo json_encode($r,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE);exit;}
}catch(Throwable $e){$error='Pemeriksaan tidak selesai: '.$e->getMessage();}
$history=$health->history();$report??=$history[0]??null;$search=trim((string)($_GET['search']??''));$status=(string)($_GET['status']??'');$category=(string)($_GET['category']??'');
$rows=array_values(array_filter($history,fn($r)=>($search===''||stripos($r['id'].' '.$r['mode'].' '.$r['status'],$search)!==false)&&($status===''||$r['status']===$status)));$page=max(1,(int)($_GET['page']??1));$total=count($rows);$rows=array_slice($rows,($page-1)*15,15);
page_head('Pemeriksaan Kesehatan Sistem','update_system');page_title('Pemeriksaan Kesehatan Sistem','Diagnostik read-only Central dan seluruh cabang; hasil parsial bukan bukti aman.');
?><link rel="stylesheet" href="assets/css/system-update.css"><div class="page-actions"><a class="btn" href="update_system.php">Update Sistem</a><a class="btn" href="backup.php">Backup Database</a><a class="btn" href="#health-history">Riwayat</a></div><?php if($error):?><div class="alert alert-danger" role="alert"><?= e($error) ?></div><?php endif;?>
<div class="system-grid"><section class="card system-wide"><div class="card-body"><h2><?= e($report['status']??'Belum Diperiksa') ?></h2><p>Skor: <strong><?= isset($report)?(int)$report['score'].' / 100':'—' ?></strong> · Cakupan pemeriksaan selesai: <strong><?= isset($report)?(int)$report['coverage'].'%':'0%' ?></strong> · Terakhir: <?= e($report['created_at']??'Belum diperiksa') ?></p><p>Skor = jumlah bobot × nilai status / seluruh bobot: Lulus 1, Peringatan 0,5, Kritis/Tidak Dapat Diperiksa 0. Cakupan = bobot pemeriksaan yang selesai / seluruh bobot.</p><?php if($report):?><p>Lulus <?= $report['counts']['pass'] ?> · Peringatan <?= $report['counts']['warning'] ?> · Kritis <?= $report['counts']['critical'] ?> · Tidak Dapat Diperiksa <?= $report['counts']['unavailable'] ?></p><?php endif;?>
<form method="post" class="system-form"><?= csrf_field() ?><input type="hidden" name="action" value="run"><div class="field"><label for="health-mode">Mode pemeriksaan</label><select class="input" id="health-mode" name="mode"><option value="quick">Cepat — koneksi, registry, versi, metadata backup, konfigurasi</option><option value="deep">Mendalam — integrity/FK, struktur, arsip, checksum media</option></select><div class="hint">Mendalam menjangkau semua cabang; batas pemindaian sekitar 45 detik. Jalankan saat sepi. Batas waktu diperiksa antaroperasi. Runtime tanpa pengendali interrupt SQLite dapat menyelesaikan query yang sedang berjalan melewati batas ini.</div></div><button class="btn btn-primary">Periksa Sekarang</button></form>
<?php if($report):?><div class="system-actions mt-2"><a class="btn" href="?export=<?= e($report['id']) ?>">Ekspor JSON</a><button class="btn" type="button" id="health-copy">Salin Laporan untuk Codex</button><button class="btn" type="button" id="health-print">Cetak / Simpan PDF</button></div><textarea class="input mt-2" id="health-copy-text" rows="6" readonly aria-label="Ringkasan teknis tersanitasi"><?= e($health->codex($report)) ?></textarea><p class="small muted">PDF memakai fitur cetak browser; tidak mengklaim compiler PDF server tersedia.</p><?php endif;?></div></section>
<?php foreach(NaveenaSystemHealth::CATEGORIES as $key=>$label):?><a class="card" href="?id=<?= e($report['id']??'') ?>&amp;category=<?= e($key) ?>#health-detail"><div class="card-body"><h3><?= e($label) ?></h3><?php $items=array_filter($report['checks']??[],fn($c)=>$c['category']===$key);?><p><?= count($items) ?> pemeriksaan · <?= count(array_filter($items,fn($c)=>$c['status']==='critical')) ?> kritis</p></div></a><?php endforeach;?>
<?php if($report):?><section class="card system-wide"><div class="card-body"><h2>Central &amp; Seluruh Cabang</h2><div class="table-wrap"><table class="tbl"><thead><tr><th>Database</th><th>Kode</th><th>Versi</th><th>Ukuran</th><th>Status</th></tr></thead><tbody><?php foreach($report['databases'] as $db):?><tr><td><?= e($db['database']) ?></td><td><?= e($db['code']) ?></td><td><?= e($db['version']??'Tidak terbaca') ?></td><td><?= num($db['bytes']??0) ?> byte</td><td><?= e($db['active']??$db['status']??'') ?></td></tr><?php endforeach;?></tbody></table></div></div></section><section class="card system-wide" id="health-detail"><div class="card-body"><h2>Detail <?= e(NaveenaSystemHealth::CATEGORIES[$category]??'Seluruh Kategori') ?></h2><div class="table-wrap"><table class="tbl"><thead><tr><th>Pemeriksaan / Bobot</th><th>Status / Risiko</th><th>Temuan &amp; Rekomendasi</th><th>Bukti teknis</th></tr></thead><tbody><?php foreach($report['checks'] as $c):if($category!==''&&$c['category']!==$category)continue;?><tr><td><?= e($c['name']) ?><br><span class="small muted">Bobot <?= (int)$c['weight'] ?> · <?= e($c['category']) ?></span></td><td><?= badge(['pass'=>'Lulus','warning'=>'Peringatan','critical'=>'Kritis','unavailable'=>'Tidak Dapat Diperiksa'][$c['status']],['pass'=>'green','warning'=>'yellow','critical'=>'red','unavailable'=>'gray'][$c['status']]) ?><br><?= e($c['risk']) ?></td><td><?= e($c['detail']) ?><p class="small muted"><?= e($c['recommendation']) ?></p><span class="small">Tindak lanjut: <?= e($c['follow_up']) ?></span></td><td><pre class="system-log small"><?= e(json_encode($c['evidence'],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE)) ?></pre></td></tr><?php endforeach;?></tbody></table></div></div></section><?php endif;?>
<section class="card system-wide" id="health-history"><div class="card-body"><h2>Riwayat Pemeriksaan</h2><form method="get" class="system-filters health-filters"><div class="field"><label for="health-search">Pencarian</label><input class="input" id="health-search" name="search" value="<?= e($search) ?>" placeholder="ID, mode, status"></div><div class="field"><label for="health-status">Status</label><select class="input" id="health-status" name="status"><option value="">Semua status</option><?php foreach(['Sehat','Perhatian','Kritis'] as $s):?><option <?= $s===$status?'selected':'' ?>><?= e($s) ?></option><?php endforeach;?></select></div><button class="btn">Cari / Filter</button></form><div class="table-wrap"><table class="tbl"><thead><tr><th>ID / Waktu</th><th>Mode</th><th>Status</th><th>Skor / Cakupan</th><th>Tindakan</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?= e($r['id']) ?><br><?= e($r['created_at']) ?></td><td><?= e($r['mode']) ?></td><td><?= e($r['status']) ?></td><td><?= (int)$r['score'] ?> / <?= (int)$r['coverage'] ?>%</td><td><div class="system-actions"><a class="btn btn-sm" href="?id=<?= e($r['id']) ?>">Detail</a><a class="btn btn-sm" href="?export=<?= e($r['id']) ?>">JSON</a></div></td></tr><?php endforeach;?></tbody></table></div><?= pagination($total,15,$page) ?><form method="post" class="system-form mt-2"><?= csrf_field() ?><input type="hidden" name="action" value="retention"><div class="field"><label for="health-keep">Riwayat disimpan (15–200)</label><input class="input" type="number" id="health-keep" name="keep" min="15" max="200" value="<?= $health->retention() ?>" required></div><button class="btn">Simpan Retensi</button></form></div></section></div>
<script>document.getElementById('health-copy')?.addEventListener('click',async()=>{const t=document.getElementById('health-copy-text');try{await navigator.clipboard.writeText(t.value);}catch(e){t.focus();t.select();}});document.getElementById('health-print')?.addEventListener('click',()=>window.print());</script><?php page_foot();

